    "text": "課長、今度うちの健康茶を愛用してくださっているお客様をお呼びして、ご意見を伺う予定になっていましたよね。お客様に出す案内状できたので、見ていただけますか。用紙の下半分を切り取って返信していただくようにしてみたんですが。",
